<template>
  <div class="canv_cont">
    <canvas ref="canv"></canvas>
  </div>
</template>
<script>
import Chart from "chart.js";
import moment from "moment";

export default {
  data() {
    return {
      gradient: null,
      context: null,
      options: ["year", "month", "week", "day", "hour"],
      scope: "year",
      priceHistory: null,
      chart: null,
    };
  },
  computed: {
    daysBack() {
      let days = 30;
      switch (this.scope) {
        case "year":
          days = 365;
          break;
        case "month":
          days = 30;
          break;
        case "week":
          days = 7;
          break;
        case "day":
          days = 1;
          break;
        case "hour":
          days = 1;
          break;
      }
      return days;
    },
    priceData() {
      if (!this.priceHistory) return [];
      return this.priceHistory.prices || [];
    },
    valuesX() {
      return this.priceData.map((item) => item[1]);
    },
    labelsX() {
      const res = [];
      const scope = this.scope;
      let format = "MMM DD";

      if (scope === "year") format = "MMM YYYY";
      else if (scope === "month") format = "MMM DD";
      else if (scope === "week") format = "MMM DD";
      else if (scope === "day") format = "HH:mm";
      else if (scope === "hour") format = "HH:mm";

      this.priceData.forEach((item) => {
        const date = new Date(item[0]);
        const label = moment(date).format(format);
        res.push(label);
      });

      return res;
    },
  },
  created() {
    this.updatePriceHistory();
  },
  mounted() {
    const cont = this.$refs.canv.getContext("2d");
    const gradient = cont.createLinearGradient(0, 0, cont.canvas.width, 0);
    gradient.addColorStop(0.0, "#3AAA82");
    gradient.addColorStop(0.353, "#42B28A");
    gradient.addColorStop(0.598, "#4EBEAA");
    gradient.addColorStop(1.0, "#3EC6D9");
    this.context = cont;

    const valuesX = this.valuesX;

    const myLineChart = new Chart(cont, {
      type: "line",
      maintainAspectRatio: true,
      data: {
        labels: [
          "January",
          "February",
          "March",
          "April",
          "May",
          "June",
          "July",
        ],
        datasets: [
          {
            label: "DJT Price (USD)",
            backgroundColor: gradient,
            borderColor: gradient,
            borderWidth: 2,
            pointBackgroundColor: "transparent",
            pointBorderColor: "transparent",
            pointHoverBackgroundColor: "#2df9b8",
            pointHoverBorderColor: gradient,
            data: valuesX,
            fill: false,
            tension: 0.6,
          },
        ],
      },
      options: {
        maintainAspectRatio: false,
        responsive: true,
        title: {
          display: false,
          text: "Chart.js Line Chart",
        },
        tooltips: {
          mode: "index",
          enabled: true,
          intersect: false,
        },
        legend: {
          display: false,
        },
        hover: {
          mode: "nearest",
          intersect: true,
        },
        scales: {
          x: {
            fontFamily: "MetaSerifPro-Bold",
            fontSize: 8,
            display: false,
            scaleLabel: {
              display: false,
              labelString: "Month",
            },
          },

          y: {
            fontFamily: "MetaSerifPro-Bold",
            fontSize: 8,
            display: false,
            scaleLabel: {
              display: false,
              labelString: "Value",
            },
            ticks: {
              callback: function (value, index, values) {
                return "$" + value.toFixed(2);
              },
            },
          },
          xAxes: [
            {
              gridLines: {
                color: "rgba(0, 0, 0, 0.06)",
              },
              ticks: {
                display: false,
                autoSkip: true,
                maxTicksLimit: 4,
                maxRotation: 0,
                fontFamily: "'IBM Plex Mono', 'monospace'",
                fontSize: 6,
                padding: 4,
                fontColor: "#c5c5c5",
              },
            },
          ],
          yAxes: [
            {
              gridLines: {
                color: "rgba(0, 0, 0, 0.06)",
              },
              ticks: {
                display: false,
                autoSkip: true,
                maxTicksLimit: 10,
                precision: 0,
                min: 0,
                fontFamily: "'IBM Plex Mono', 'monospace'",
                fontSize: 6,
                fontColor: "#c5c5c5",
                padding: 1,
              },
            },
          ],
        },
        animation: { duration: 1000 },
        easing: "linear",
      },
    });

    this.chart = myLineChart;
  },
  methods: {
    setScope(val) {
      this.scope = val;
      this.updatePriceHistory();
    },

    async updatePriceHistory() {
      try {
        const days = this.daysBack;
        const response = await fetch(
          `https://api.coingecko.com/api/v3/coins/near/market_chart?vs_currency=usd&days=${days}`
        );
        const data = await response.json();
        this.priceHistory = data;
        this.draw();
      } catch (error) {
        console.error("Error fetching Dijets price data:", error);
        // Fallback to mock data
        this.priceHistory = {
          prices: this.generateMockPriceData(),
        };
        this.draw();
      }
    },

    generateMockPriceData() {
      const days = this.daysBack;
      const now = Date.now();
      const data = [];
      const basePrice = 4.5; // Base DJT price

      for (let i = days; i >= 0; i--) {
        const timestamp = now - i * 24 * 60 * 60 * 1000;
        const variation = (Math.random() - 0.5) * 0.5; // ±25 cents variation
        const price = basePrice + variation + Math.sin(i / 5) * 0.3;
        data.push([timestamp, Math.max(0.1, price)]);
      }

      return data;
    },

    clearChart() {
      const chart = this.chart;
      chart.data.labels = [];
      chart.data.datasets.forEach((dataset) => {
        dataset.data = [];
      });
      chart.update();
    },
    draw() {
      this.clearChart();
      const parent = this;

      const dataX = this.valuesX;
      const labelsX = this.labelsX;
      const chart = this.chart;

      dataX.forEach((data, index) => {
        const label = labelsX[index];

        chart.data.labels.push(label);
        chart.data.datasets.forEach((dataset) => {
          dataset.data.push(data);
        });
      });
      chart.update();
    },
  },
};
</script>
